{"path": "app/backend/index.js", "content": "const express = require('express');
const cors = require('cors');
const bodyParser = require('body-parser');
const db = require('./db');
const http = require('http');
const { getBoard, createCard, moveCard } = require('./handlers/board');
const { eventEmitter, sendEvent } = require('./sse');

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(bodyParser.json());

// API routes
app.get('/api/board', async (req, res) => {
  const board = await getBoard();
  res.json(board);
});

app.post('/api/cards', async (req, res) => {
  const { columnId, text } = req.body;
  const card = await createCard(columnId, text);
  sendEvent('create', card); // broadcast
  res.json(card);
});

app.patch('/api/cards/:id/move', async (req, res) => {
  const id = parseInt(req.params.id, 10);
  const { columnId, beforeId, afterId } = req.body;
  const card = await moveCard(id, columnId, beforeId, afterId);
  sendEvent('move', card);
  res.json(card);
});

// SSE endpoint
app.get('/api/stream', (req, res) => {
  // Set headers for SSE
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  // Register connection
  const onEvent = (type, data) => {
    const payload = JSON.stringify({ type, data });
    res.write(`data: ${payload}\n\n`);
  };

  eventEmitter.on('event', onEvent);

  req.on('close', () => {
    eventEmitter.off('event', onEvent);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Kanban server listening on port ${PORT}`);
});
"}

{"path": "app/backend/handlers/board.js", "content": "const db = require('../db');

async function getBoard() {
  const { rows: columns } = await db.query('SELECT id, title, position FROM columns ORDER BY position;');
  const board = [];
  for (const col of columns) {
    const { rows: cards } = await db.query('SELECT id, column_id, text, position, created_at FROM cards WHERE column_id = ? ORDER BY position;', [col.id]);
    board.push({
      id: col.id,
      title: col.title,
      position: col.position,
      cards: cards.map(c => ({ id: c.id, columnId: c.column_id, text: c.text, position: c.position, createdAt: c.created_at }))
    });
  }
  return board;
}

async function createCard(columnId, text) {
  // find max position
  const { rows } = await db.query('SELECT MAX(position) as maxPos FROM cards WHERE column_id = ?;', [columnId]);
  const maxPos = rows[0].maxPos || 0;
  const position = maxPos + 1;
  const { insertId } = await db.query('INSERT INTO cards (column_id, text, position, created_at) VALUES (?, ?, ?, datetime('now'));', [columnId, text, position]);
  const card = {
    id: insertId,
    columnId,
    text,
    position,
    createdAt: new Date().toISOString()
  };
  return card;
}

async function moveCard(id, columnId, beforeId, afterId) {
  // compute new position
  let between = [];
  if (beforeId) {
    const { rows } = await db.query('SELECT position FROM cards WHERE id = ?;', [beforeId]);
    between.push(rows[0].position);
  }
  if (afterId) {
    const { rows } = await db.query('SELECT position FROM cards WHERE id = ?;', [afterId]);
    between.push(rows[0].position);
  }
  let newPos;
  const epsilon = 0.000001;
  if (between.length === 2) {
    newPos = (between[0] + between[1]) / 2;
  } else if (between.length === 1) {
    // only one side
    if (beforeId) {
      newPos = between[0] + epsilon;
    } else if (afterId) {
      newPos = between[0] - epsilon;
    }
  } else {
    // no reference: place at end
    const { rows } = await db.query('SELECT MAX(position) as maxPos FROM cards WHERE column_id = ?;', [columnId]);
    newPos = (rows[0].maxPos || 0) + 1;
  }
  // perform update
  await db.exec(`BEGIN;`);
  await db.query(`UPDATE cards SET column_id = ?, position = ? WHERE id = ?;`, [columnId, newPos, id]);
  await db.exec(`COMMIT;`);

  const { rows: c } = await db.query('SELECT id, column_id, text, position, created_at FROM cards WHERE id = ?;', [id]);
  const card = c[0];
  return {
    id: card.id,
    columnId: card.column_id,
    text: card.text,
    position: card.position,
    createdAt: card.created_at
  };
}

module.exports = { getBoard, createCard, moveCard };
"}

